# -*- coding: utf-8 -*-
from ._helpers import intro, schema, fall, mc

KURS = dict(
    id="u10", gebiet="upc", titel="EPGÜ und Durchsetzungsrichtlinie: eine Richtlinie, drei Gesetze",
    untertitel="Warum Art. 59 bis 69 und 80 EPGÜ dieselbe Struktur haben wie §§ 139 bis 140e PatG und §§ 18 bis 19c MarkenG",
    farbe="#8b3fb2", icon="richtlinie",
    beschreibung="Die Durchsetzungsrichtlinie 2004/48/EG ist der gemeinsame Nenner: Beweisvorlage, Beweissicherung, Auskunft, einstweilige Maßnahmen, Abhilfe, Unterlassung, Schadensersatz, Kosten und Veröffentlichung stehen im EPGÜ (Art. 59 bis 69, 80), im PatG (§§ 139 bis 140e) und im MarkenG (§§ 14, 18 bis 19c). Der Kurs zeigt die Entsprechungen und wie das Berufungsgericht das EPGÜ richtlinienkonform auslegt: hinreichende Sicherheit (NanoString/10x), Beweissicherung (Centripetal/Palo Alto), Mittelspersonen und Verletzerbegriff (Belkin/Philips), Kostenobergrenzen und Schadensersatz ohne Strafcharakter.",
    kapitel=[
        dict(id="u10a", titel="Die Entsprechungen: Richtlinie, EPGÜ, PatG, MarkenG", einheiten=[
            intro("u10a-0", "Eine Richtlinie, drei Gesetze",
                  "Die **Durchsetzungsrichtlinie 2004/48/EG** verpflichtet die Mitgliedstaaten, für alle Rechte des geistigen Eigentums dieselben Maßnahmen, Verfahren und Rechtsbehelfe bereitzustellen: Beweisvorlage (Art. 6), Beweissicherung (Art. 7), Auskunft (Art. 8), einstweilige Maßnahmen (Art. 9), Abhilfemaßnahmen (Art. 10), gerichtliche Anordnungen einschließlich solcher gegen Mittelspersonen (Art. 11), Schadensersatz (Art. 13), Prozesskosten (Art. 14) und Veröffentlichung (Art. 15) – alles fair, wirksam, verhältnismäßig und abschreckend (Art. 3). Deutschland hat sie 2008 mit dem Durchsetzungsgesetz als Artikelgesetz umgesetzt: im PatG als §§ 139 bis 140e, im MarkenG als §§ 14, 18, 19 bis 19c. Das **EPGÜ** setzt dieselbe Richtlinie für das gemeinsame Gericht um, und zwar in seinem Teil über Befugnisse des Gerichts: **Art. 59 EPGÜ ↔ Art. 6 RL** (Beweisvorlage), **Art. 60 ↔ Art. 7** (Beweissicherung und Besichtigung), **Art. 67 ↔ Art. 8** (Auskunft), **Art. 62 ↔ Art. 9** (einstweilige Maßnahmen), **Art. 64 ↔ Art. 10** (Rückruf, Entfernung, Vernichtung), **Art. 63 ↔ Art. 11** (Unterlassung, Mittelspersonen), **Art. 68 ↔ Art. 13** (Schadensersatz), **Art. 69 ↔ Art. 14** (Kosten), **Art. 80 ↔ Art. 15** (Veröffentlichung). Weil das EPG als gemeinsames Gericht der Mitgliedstaaten an das Unionsrecht gebunden ist (Art. 1 Abs. 2, Art. 20 EPGÜ) und die Richtlinie nach Art. 24 Abs. 1 lit. a EPGÜ vorrangige Rechtsquelle ist, legt das Berufungsgericht die Vorschriften des EPGÜ **richtlinienkonform** aus und greift auf die Rechtsprechung des EuGH zur Richtlinie zurück. Die Tabelle zeigt die Zuordnung Artikel für Artikel mit den Regeln der VerfO und den deutschen Parallelnormen. Für die Klausur heißt das: Wer § 140b PatG oder § 19 MarkenG kennt, kennt Art. 67 EPGÜ; die Unterschiede liegen im Verfahren (Ermessen des Gerichts, Antrag, R. 191 VerfO), nicht in der Struktur.",
                  concepts=["upc_durchsetzungsrl_bezug", "durchsetzungsrl"], norms=["Art. 24 EPGÜ", "Art. 3 DurchsetzungsRL", "Art. 63 EPGÜ", "Art. 11 DurchsetzungsRL"],
                  distinctions=["d_upc_entsprechung_durchsetzungsrl"]),
            fall("u10a-1", "Hinreichende Sicherheit – wie sicher?",
                 "10x Genomics beantragt gegen NanoString einstweilige Maßnahmen aus einem Einheitspatent. NanoString bestreitet die Verletzung und hält das Patent für nicht rechtsbeständig. Die Lokalkammer erlässt die Anordnung, weil sie Berechtigung und Verletzung für überwiegend wahrscheinlich hält. NanoString meint in der Berufung, „hinreichende Sicherheit“ nach R. 211.2 VerfO verlange, dass das Gericht von der Verletzung und dem Rechtsbestand **überzeugt** sei wie in der Hauptsache; alles andere verstoße gegen Art. 62 Abs. 4 EPGÜ.",
                 "Muss das Gericht für einstweilige Maßnahmen von Verletzung und Rechtsbestand mit der Sicherheit eines Hauptsacheverfahrens überzeugt sein?", False,
                 ["**Nein!** Art. 62 Abs. 4 EPGÜ und R. 211.2 VerfO verlangen, dass das Gericht sich mit **hinreichender Sicherheit** davon überzeugt, dass der Antragsteller berechtigt ist und das Patent verletzt wird oder eine Verletzung droht. Das Berufungsgericht legt diesen Maßstab **richtlinienkonform** anhand von Art. 9 Abs. 3 DurchsetzungsRL aus, wonach der Antragsteller „mit ausreichender Sicherheit“ nachweisen muss, dass er Rechtsinhaber ist und sein Recht verletzt wird oder eine Verletzung droht. Hinreichend ist die Sicherheit, wenn das Gericht Berechtigung und Verletzung für **überwiegend wahrscheinlich** hält; sie fehlt, wenn es die Nichtigkeit des Patents für überwiegend wahrscheinlich hält (EPG-BerG NanoString/10x Genomics).",
                  "Der summarische Charakter des Eilverfahrens erlaubt keine Hauptsache-Gewissheit; das gleicht die VerfO durch die Interessenabwägung (R. 211.3), die Dringlichkeit (R. 211.4), die Sicherheitsleistung (R. 211.5) und den Schadensersatz bei Aufhebung (Art. 62 Abs. 5 i.V.m. Art. 60 Abs. 9 EPGÜ, Art. 9 Abs. 7 RL) aus. Die Darlegungs- und Beweislast trägt für Berechtigung und Verletzung der Antragsteller, für die Nichtigkeit der Antragsgegner. Im deutschen Recht entspricht dem die Glaubhaftmachung nach §§ 935, 940 ZPO, § 294 ZPO; die Dringlichkeitsvermutung des § 140 Abs. 3 MarkenG kennt weder die Richtlinie noch das EPGÜ."],
                 merke="Hinreichende Sicherheit = überwiegende Wahrscheinlichkeit, richtlinienkonform aus Art. 9 Abs. 3 RL – nicht die Überzeugung der Hauptsache.",
                 level=2, concepts=["upc_hinreichende_sicherheit", "upc_durchsetzungsrl_bezug"], norms=["Art. 62 Abs. 4 EPGÜ", "R. 211.2 VerfO", "Art. 9 Abs. 3 DurchsetzungsRL"],
                 cases=["upc_coa_nanostring_10x"], step="step:upc_schema_einstweilige_massnahmen.2.1"),
            fall("u10a-2", "Beweissicherung ohne Beweis",
                 "Centripetal vermutet, dass die Firewall-Software von Palo Alto ein Verfahren ihres Patents ausführt, kann das aber von außen nicht belegen, weil der Quellcode nicht zugänglich ist. Sie beantragt eine Ex-parte-Anordnung zur Beweissicherung mit Besichtigung nach Art. 60 EPGÜ und legt Produktdokumentation und ein Sachverständigengutachten vor, die eine Verletzung plausibel machen. Palo Alto meint, Centripetal müsse die Verletzung so nachweisen wie ein Verletzungskläger, sonst sei die Besichtigung eine unzulässige Ausforschung.",
                 "Gilt für die Beweissicherung das Beweismaß der Verletzungsklage?", False,
                 ["**Nein!** Art. 60 Abs. 1 EPGÜ verlangt, dass der Antragsteller alle **vernünftigerweise verfügbaren Beweismittel** zur Begründung seiner Behauptung vorlegt, dass das Patent verletzt wurde oder verletzt zu werden droht – die Umsetzung von Art. 7 Abs. 1 DurchsetzungsRL, der dieselbe Formel verwendet. Das ist eine **niedrigere Hürde** als die Beweislast des Verletzungsklägers, gerade für Aspekte, zu denen der Antragsteller keinen Zugang hat; der Zweck der Beweissicherung besteht ja darin, Beweise zu beschaffen, die ihm fehlen. Das Beweismaß darf im summarischen Verfahren weder zu hoch noch zu niedrig angesetzt werden (EPG-BerG Centripetal/Palo Alto).",
                  "Bloße Spekulation genügt nicht: Um „fishing expeditions“ zu verhindern, muss die Verletzung **plausibel** sein, bei Ex-parte-Anordnungen umso mehr, und der Antragsteller muss alle ihm bekannten wesentlichen Tatsachen offenlegen (R. 192.3 VerfO; Ecovacs/Roborock). Die Besichtigung greift in Art. 7 GRCh ein und verlangt wirksame Schutzvorkehrungen, etwa Vertraulichkeitsanordnungen (R. 196, R. 262A VerfO). Das deutsche Recht setzt Art. 7 RL in § 140c PatG und § 19a MarkenG um, dort mit dem Merkmal der „hinreichenden Wahrscheinlichkeit“ der Verletzung, das der BGH in Faxkarte und Restschadstoffentfernung ebenso als abgesenktes Beweismaß versteht."],
                 merke="Art. 60 EPGÜ, Art. 7 RL: vernünftigerweise verfügbare Beweise und Plausibilität – die Besichtigung soll den Beweis erst beschaffen.",
                 level=3, concepts=["upc_beweissicherung", "upc_durchsetzungsrl_bezug"], norms=["Art. 60 Abs. 1 EPGÜ", "R. 194 VerfO", "Art. 7 DurchsetzungsRL"],
                 cases=["upc_coa_centripetal_paloalto_beweissicherung", "upc_coa_ecovacs_roborock_exparte"], step="step:upc_schema_beweissicherung.2.1"),
            mc("u10a-3", "Verletzer und Mittelspersonen: Art. 63 EPGÜ und Art. 11 RL",
                "Welche Aussage trifft zu?",
                ["Gegen den Logistikdienstleister kann eine Anordnung nach Art. 63 Abs. 1 Satz 2 EPGÜ ergehen, auch wenn er selbst kein Verletzer ist; der Geschäftsführer haftet dagegen nicht allein wegen seiner Organstellung.",
                 "Anordnungen gegen Mittelspersonen kennt das EPGÜ nicht; Art. 11 Satz 3 DurchsetzungsRL gilt nur für nationale Gerichte.",
                 "Der Geschäftsführer ist als Organ stets Verletzer im Sinne des Art. 63 EPGÜ, weil ihm die Handlungen der Gesellschaft zugerechnet werden.",
                 "Ob jemand Verletzer ist, bestimmt das EPG nach dem nationalen Recht des Kammerstaats, im Fall der Lokalkammer Düsseldorf also nach § 139 PatG und § 830 BGB."],
                0,
                ["**Richtig ist die erste Aussage.** Art. 63 Abs. 1 Satz 2 EPGÜ erlaubt eine Verfügung gegen **Mittelspersonen**, deren Dienste von einem Dritten zwecks Patentverletzung in Anspruch genommen werden; das ist die wörtliche Umsetzung von Art. 11 Satz 3 DurchsetzungsRL, den der EuGH für Marktplätze und Provider weit versteht (L'Oréal/eBay, Tommy Hilfiger/Delta Center). Ein Logistikdienstleister, über dessen Lager die Geräte ausgeliefert werden, ist eine solche Mittelsperson; eigene Verletzerhaftung ist nicht erforderlich. Die zweite Aussage ist deshalb falsch.",
                 "Die dritte und die vierte Aussage verkennen den Verletzerbegriff: Verletzer nach Art. 63 EPGÜ ist auch, wem die Handlungen Dritter als Anstifter, Mittäter oder Gehilfe zuzurechnen sind, und die Zurechnung bestimmt sich durch **autonome Auslegung** des EPGÜ, nicht nach nationalem Recht. Die bloße Organstellung macht den Geschäftsführer nicht zum Mittäter; er haftet nur, wenn er das Unternehmen zweckgerichtet zur Verletzung nutzt oder trotz Kenntnis und Zumutbarkeit nicht einschreitet (EPG-BerG Belkin/Philips). Das deutsche Recht kommt über § 139 PatG und die Störerhaftung zu ähnlichen Ergebnissen, mit einer traditionell strengeren Geschäftsführerhaftung, die der BGH seit Geschäftsführerhaftung (I ZR 242/12) ebenfalls auf die Verletzung eigener Pflichten begrenzt."],
                sachverhalt="Philips erwirkt gegen Belkin eine Unterlassungsanordnung wegen des Anbietens patentverletzender Ladegeräte und will die Anordnung auf den Geschäftsführer von Belkin und auf den Logistikdienstleister erstrecken, über dessen Lager die Geräte ausgeliefert werden.",
                merke="Art. 63 EPGÜ ist Art. 11 RL: Mittelspersonen ja, Organstellung allein nein – und der Verletzerbegriff ist autonom.",
                level=2, concepts=["upc_verletzer", "upc_unterlassungsanordnung", "upc_durchsetzungsrl_bezug"], norms=["Art. 63 Abs. 1 EPGÜ", "Art. 11 DurchsetzungsRL"],
                cases=["upc_coa_belkin_philips_anbieten"], step="step:upc_schema_verletzungsklage.3.1"),
        ]),
        dict(id="u10b", titel="Schadensersatz, Kosten und Veröffentlichung (Art. 68, 69, 80 EPGÜ ↔ Art. 13, 14, 15 RL)", einheiten=[
            intro("u10b-0", "Dieselben Rechtsfolgen, drei Adressen",
                  "**Schadensersatz**: Art. 13 Abs. 1 DurchsetzungsRL verlangt Ersatz für den Verletzer, der wusste oder vernünftigerweise hätte wissen müssen, dass er eine Verletzung begeht, bemessen entweder nach allen Aspekten einschließlich Gewinneinbußen, Verletzergewinn und immateriellem Schaden (lit. a) oder als Pauschale auf Grundlage mindestens der hypothetischen Lizenzgebühr (lit. b); für den gutgläubigen Verletzer erlaubt Abs. 2 die Herausgabe der Gewinne oder eine Entschädigung. Art. 68 EPGÜ übernimmt das nahezu wörtlich und fügt in Abs. 2 hinzu, dass der Schadensersatz keinen Strafcharakter hat; § 139 Abs. 2 PatG und § 14 Abs. 6 MarkenG enthalten dieselben drei Berechnungsarten, gehen aber mit der Verschuldenshaftung nach deutschem Muster (Vorsatz oder Fahrlässigkeit) über die Richtlinie hinaus, was Art. 2 Abs. 1 RL als günstigere Regelung erlaubt. **Kosten**: Art. 14 RL will, dass die Prozesskosten und sonstigen Kosten der obsiegenden Partei in der Regel von der unterlegenen Partei getragen werden, soweit sie **zumutbar und angemessen** sind und Billigkeitsgründe nicht entgegenstehen; Art. 69 Abs. 1 EPGÜ wiederholt das und ergänzt die **Obergrenze** nach der Verfahrensordnung, die der EuGH in United Video Properties für Pauschalen des nationalen Rechts gebilligt hat, sofern ein erheblicher und angemessener Teil der tatsächlichen Kosten erstattet wird. Im deutschen Recht leisten §§ 91 ff. ZPO mit der Erstattung nach RVG und der Streitwertbegünstigung des § 144 PatG dasselbe. **Veröffentlichung**: Art. 15 RL, Art. 80 EPGÜ, § 140e PatG und § 19c MarkenG erlauben auf Antrag des Obsiegenden und auf Kosten des Verletzers die Bekanntmachung der Entscheidung. Die Unterschiede liegen im Verfahren: Das EPG setzt die Höhe des Schadensersatzes im gesonderten Verfahren nach R. 125 ff. VerfO fest, die Kosten nach R. 150 ff. VerfO – anders als die deutsche Stufenklage mit Auskunft, Rechnungslegung und Bezifferung.",
                  concepts=["upc_schadensersatz", "upc_kostenerstattung", "upc_durchsetzungsrl_bezug"], norms=["Art. 68 EPGÜ", "Art. 13 DurchsetzungsRL", "Art. 69 Abs. 1 EPGÜ", "Art. 14 DurchsetzungsRL"]),
            fall("u10b-1", "Die doppelte Lizenz vor dem EPG",
                 "Nach rechtskräftiger Verurteilung beantragt Helion im Verfahren nach R. 125 ff. VerfO die Festsetzung des Schadensersatzes gegen Solvix. Helion verlangt das **Doppelte** der üblichen Lizenzgebühr: Solvix habe die Verletzung gekannt und trotz Abmahnung fortgesetzt; ein Verletzerzuschlag sei nötig, damit sich die Verletzung nicht lohne, und Art. 13 DurchsetzungsRL stehe dem als Mindestharmonisierung nicht entgegen.",
                 "Kann das EPG den Schadensersatz als Verletzerzuschlag auf das Doppelte der Lizenzgebühr festsetzen?", False,
                 ["**Nein!** Art. 68 Abs. 2 Satz 3 EPGÜ bestimmt ausdrücklich, dass der Schadensersatz **keinen Strafcharakter** hat. Die Pauschale nach Art. 68 Abs. 3 lit. b EPGÜ wird auf Grundlage von Faktoren wie „mindestens“ der Lizenzgebühr festgesetzt, die der Verletzer bei Einholung der Erlaubnis hätte zahlen müssen; das „mindestens“ öffnet den Betrag für Zinsen, Rechtsverfolgungsaufwand und die Unsicherheiten der Lizenzanalogie, nicht für einen Zuschlag als Sanktion. Ziel ist der Ausgleich des tatsächlichen Schadens (Abs. 1) und die Abschöpfung des Nutzens (Abs. 2 Satz 2), nicht die Bestrafung.",
                  "Die Richtlinie ändert daran nichts: Art. 13 Abs. 1 lit. b DurchsetzungsRL ist Vorbild der EPGÜ-Pauschale, und Erwägungsgrund 26 will keine Verpflichtung zu Strafschadensersatz einführen. Zwar hat der EuGH in OTK (C-367/15) eine nationale Regelung mit doppelter Lizenzgebühr als günstigere Vorschrift nach Art. 2 Abs. 1 RL gebilligt; das EPGÜ hat diese Option aber gerade nicht gezogen, sondern in Art. 68 Abs. 2 das Gegenteil festgeschrieben. Auch das deutsche Recht kennt keinen Verletzerzuschlag: § 139 Abs. 2 PatG und § 14 Abs. 6 MarkenG gewähren die einfache Lizenzanalogie. Helion kann stattdessen den Verletzergewinn oder den entgangenen Gewinn wählen (Art. 68 Abs. 3 lit. a EPGÜ) und die Offenlegung der Bücher verlangen (R. 131.1 lit. c, R. 141 VerfO)."],
                 merke="Art. 68 Abs. 2 EPGÜ: Ausgleich und Abschöpfung, keine Strafe – die Mindestharmonisierung der Richtlinie erlaubt mehr, das EPGÜ nutzt es nicht.",
                 level=2, concepts=["upc_schadensersatz", "upc_durchsetzungsrl_bezug"], norms=["Art. 68 Abs. 2 EPGÜ", "Art. 68 Abs. 3 EPGÜ", "Art. 13 DurchsetzungsRL", "Art. 2 DurchsetzungsRL"],
                 step="step:upc_schema_verletzungsklage.3.3"),
            fall("u10b-2", "Die Obergrenze und die Richtlinie",
                 "Ilion hat gegen Tarsus obsiegt und Vertretungskosten von 1,2 Mio. EUR aufgewandt, weil das Verfahren drei Patente, zwei Sachverständige und eine Widerklage umfasste. Die Obergrenze für den festgesetzten Streitwert liegt bei 600.000 EUR. Ilion meint, die Obergrenze verstoße gegen Art. 14 DurchsetzungsRL, weil sie nicht einmal die Hälfte ihrer tatsächlichen, angemessenen Kosten erstatte; die Vorschrift sei richtlinienkonform unangewendet zu lassen.",
                 "Verstößt die Kostenobergrenze des Art. 69 Abs. 1 EPGÜ gegen Art. 14 DurchsetzungsRL?", False,
                 ["**Nein!** Art. 14 DurchsetzungsRL verlangt, dass die Prozesskosten der obsiegenden Partei „in der Regel“ von der unterlegenen Partei getragen werden, soweit sie **zumutbar und angemessen** sind und Billigkeitsgründe nicht entgegenstehen. Art. 69 Abs. 1 EPGÜ übernimmt diese Formel und fügt die **Obergrenze** nach der Verfahrensordnung hinzu (R. 152.2 VerfO, Tabelle des Verwaltungsausschusses). Der EuGH hat in United Video Properties (C-57/15) Pauschalen und Höchstbeträge für vereinbar mit Art. 14 erklärt, solange sie sicherstellen, dass ein **erheblicher und angemessener Teil** der tatsächlich entstandenen zumutbaren Kosten erstattet wird; unzulässig wären nur Grenzen, die so niedrig liegen, dass sie die Durchsetzung abschrecken.",
                  "Die Obergrenzen des EPG sind streitwertgestaffelt und reichen bis in den Millionenbereich; die Tabelle erlaubt bei besonderer Komplexität oder mehreren Sprachen eine Anhebung auf Antrag und bei wirtschaftlicher Existenzgefährdung eine Absenkung. Ilion muss also die Anhebung im Kostenfestsetzungsverfahren beantragen (R. 152, R. 156 VerfO), statt die Obergrenze zu verwerfen; im Übrigen bleibt es dabei, dass 600.000 EUR ein erheblicher Teil der Kosten ist. Das deutsche Recht liegt mit der RVG-Erstattung typischerweise weit darunter, und § 144 PatG erlaubt sogar die Streitwertbegünstigung zu Lasten des Obsiegenden – auch das hat der EuGH nicht beanstandet, solange die Erstattung nicht bedeutungslos wird."],
                 merke="Art. 14 RL erlaubt Obergrenzen, wenn ein erheblicher und angemessener Teil erstattet wird – im EPG hilft der Antrag auf Anhebung, nicht die Nichtanwendung.",
                 level=3, concepts=["upc_kostenerstattung", "upc_durchsetzungsrl_bezug"], norms=["Art. 69 Abs. 1 EPGÜ", "R. 152 VerfO", "Art. 14 DurchsetzungsRL"],
                 step="step:upc_schema_verletzungsklage.3.4"),
            mc("u10b-3", "Welche Norm gehört zu welcher?",
                "Welche Zuordnung von Durchsetzungsrichtlinie, EPGÜ und deutschem Recht ist richtig?",
                ["Art. 10 RL (Abhilfemaßnahmen) ↔ Art. 64 EPGÜ ↔ § 140a PatG, § 18 MarkenG",
                 "Art. 8 RL (Auskunft) ↔ Art. 59 EPGÜ ↔ § 140c PatG, § 19a MarkenG",
                 "Art. 9 RL (einstweilige Maßnahmen) ↔ Art. 60 EPGÜ ↔ § 140b PatG, § 19 MarkenG",
                 "Art. 15 RL (Veröffentlichung) ↔ Art. 69 EPGÜ ↔ § 140e PatG, § 19c MarkenG"],
                0,
                ["**Richtig ist die erste Zuordnung.** Art. 10 DurchsetzungsRL verlangt Rückruf, endgültiges Entfernen aus den Vertriebswegen und Vernichtung auf Kosten des Verletzers unter Wahrung der Verhältnismäßigkeit; Art. 64 EPGÜ setzt das für das EPG um (mit der zusätzlichen Option der Beseitigung der verletzenden Eigenschaft), § 140a PatG und § 18 MarkenG für die deutschen Gerichte.",
                 "Die anderen Zuordnungen sind verschoben: **Art. 8 RL** (Auskunft) entspricht Art. 67 EPGÜ, § 140b PatG und § 19 MarkenG; Art. 59 EPGÜ, § 140c PatG und § 19a MarkenG setzen dagegen **Art. 6 RL** (Beweisvorlage) um. **Art. 9 RL** (einstweilige Maßnahmen) entspricht Art. 62 EPGÜ und im deutschen Recht §§ 935 ff. ZPO; Art. 60 EPGÜ ist die Beweissicherung nach **Art. 7 RL**. **Art. 15 RL** (Veröffentlichung) entspricht Art. 80 EPGÜ, § 140e PatG und § 19c MarkenG; Art. 69 EPGÜ regelt die Kosten nach **Art. 14 RL**. Merkhilfe: Die Artikel des EPGÜ folgen der Reihenfolge des Verfahrens (Beweis 59, 60 – Eilmaßnahmen 61, 62 – Rechtsfolgen 63, 64, 67, 68 – Kosten 69 – Veröffentlichung 80), die Richtlinie derselben Logik (6, 7 – 9 – 10, 11, 13 – 14 – 15)."],
                merke="Beweis 59/60 ↔ 6/7, Eil 62 ↔ 9, Unterlassung 63 ↔ 11, Abhilfe 64 ↔ 10, Auskunft 67 ↔ 8, Schaden 68 ↔ 13, Kosten 69 ↔ 14, Veröffentlichung 80 ↔ 15.",
                level=1, concepts=["upc_durchsetzungsrl_bezug", "upc_abhilfemassnahmen"], norms=["Art. 64 EPGÜ", "Art. 10 DurchsetzungsRL", "Art. 67 EPGÜ", "Art. 8 DurchsetzungsRL"],
                step="step:upc_schema_verletzungsklage.3.2"),
        ]),
    ],
)
